-- 修复初始化导入时字符集用错导致的 UTF-8→CP1252 双重编码乱码（生产实测 76 行）
-- 现象：角色权限/账号管理/数据字典等页面中文显示为 ä¸“ä¸šç‰ˆ 等乱码
-- 根因：SQL 源文件是干净 UTF-8，导入时连接字符集按 Latin1/CP1252 解读后再 UTF-8 编码写库
-- 幂等：每条 UPDATE 带 HEX(col)=原乱码字节 条件，修复后 HEX 变化，重复执行自动跳过
-- 覆盖：t_role.name / t_sys_agent_learning.remark / t_sys_dict.name / t_sys_dict_item.name
--       / t_sys_tool_agent_context.context_key / t_sys_tool_agent_context.remark
SET NAMES utf8mb4;

UPDATE `db_admin`.`t_role` SET `name`=CONVERT(UNHEX('e4b893e4b89ae78988') USING utf8mb4) WHERE `id`=26138972975989575 AND HEX(`name`)='C3A4C2B8E2809CC3A4C2B8C5A1C3A7E280B0CB86';
